import xarray as xr
import numpy as np

def test_broadcasting():
    hya = xr.DataArray([1, 2, 3], dims={'lev': 3})
    hyb = xr.DataArray([4, 5, 6], dims={'lev': 3})
    psfc = np.random.rand(10, 20, 30)

    print("Trying hyb * psfc (hyb is xr, psfc is np):")
    try:
        res = hyb * psfc
        print("Success! Result shape:", res.shape)
    except Exception as e:
        print("Failed:", e)

    print("\nTrying hyb * xr.DataArray(psfc) (both are xr):")
    try:
        res = hyb * xr.DataArray(psfc)
        print("Success! Result shape:", res.shape)
    except Exception as e:
        print("Failed:", e)

if __name__ == "__main__":
    test_broadcasting()

